#include <queue>
using namespace std;

class SeatManager {
    priority_queue<int, vector<int>, greater<int>> pq;
    int next = 1;

public:
    SeatManager(int n) {
        for (int i = 1; i <= n; ++i) pq.push(i);
    }

    int reserve() {
        int res = pq.top(); pq.pop();
        return res;
    }

    void unreserve(int seatNumber) {
        pq.push(seatNumber);
    }
};
